CREATE TABLE IF NOT EXISTS accounts (id uuid PRIMARY KEY,email text UNIQUE NOT NULL,display_name text NOT NULL,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS credentials (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,kind text NOT NULL CHECK(kind IN ('session','api')),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz,expires_at timestamptz);
CREATE TABLE IF NOT EXISTS preferences (user_id uuid PRIMARY KEY REFERENCES accounts(id) ON DELETE CASCADE,value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS podcasts (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,script jsonb NOT NULL,scene text NOT NULL,status text NOT NULL DEFAULT 'draft',progress integer NOT NULL DEFAULT 0,stage text NOT NULL DEFAULT '等待制作',error text,duration_seconds double precision,playback_position_seconds double precision NOT NULL DEFAULT 0,completed boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,output_dir text);
CREATE INDEX IF NOT EXISTS podcasts_owner_idx ON podcasts(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY,podcast_id uuid NOT NULL REFERENCES podcasts(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,request_id uuid NOT NULL, status text NOT NULL DEFAULT 'queued',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,request_id));
CREATE UNIQUE INDEX IF NOT EXISTS jobs_one_active_idx ON jobs(podcast_id) WHERE status IN ('queued','generating','mixing');
CREATE TABLE IF NOT EXISTS events (id bigserial PRIMARY KEY,podcast_id uuid NOT NULL REFERENCES podcasts(id) ON DELETE CASCADE,status text NOT NULL,stage text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
